.humi-app{--humi-ink:#194236;--humi-primary:#186a54;--humi-line:#d9e8df;color:var(--humi-ink);background:#fff;border:1px solid var(--humi-line);border-radius:16px;max-width:1100px;padding:clamp(12px,2vw,24px);font:14px/1.5 system-ui,-apple-system,sans-serif;box-sizing:border-box}
.humi-app *{box-sizing:border-box}
.humi-hero{border-bottom:1px solid var(--humi-line);padding-bottom:9px}.humi-kicker{color:#5c8070;font-size:10px;font-weight:800;letter-spacing:.11em}.humi-app h2{font-size:clamp(22px,3vw,28px);margin:0 0 5px;line-height:1.2}.humi-app h3{font-size:18px;margin:12px 0 3px}.humi-app h4{font-size:14px;margin:14px 0 5px}.humi-hero p,.humi-help{color:#517363;margin:3px 0 7px}.humi-page{padding:12px 0}.humi-meta{font-size:12px;color:#647a6f;margin:2px 0 10px}.humi-note{font-size:12px;color:#597a6b}.humi-steps{display:flex;gap:7px;margin:12px 0;flex-wrap:wrap}.humi-step{font-size:11px;padding:5px 9px;border:1px solid var(--humi-line);background:#f5f8f5;border-radius:20px;color:#5a7267}.humi-step.current{background:#dceee3;border-color:#a5d2b9;color:#165540;font-weight:750}.humi-step.complete{background:#e7f3ee;color:#27735c}
.humi-field{display:flex;flex-direction:column;gap:5px;margin:9px 0;color:#335d4b;font-weight:650;font-size:12px}.humi-app input[type=text],.humi-app input[type=number],.humi-app input[type=file]{border:1px solid #bbd0c5;border-radius:8px;background:#fff;color:#1f4438;font:14px system-ui;min-height:38px;padding:7px 9px;max-width:100%;width:100%}.humi-title{max-width:570px!important}.humi-range{display:flex;gap:13px;max-width:330px}.humi-range>.humi-field{flex:1}.humi-range input{min-width:0}.humi-voices{max-height:260px;overflow:auto;border:1px solid var(--humi-line);background:#f9fcf9;padding:8px 12px;border-radius:10px}.humi-check,.humi-ack{display:flex;align-items:flex-start;gap:10px;padding:7px 4px;cursor:pointer}.humi-check+.humi-check{border-top:1px solid #edf3ee}.humi-app input[type=checkbox]{accent-color:#186a54;margin-top:3px;flex:none}.humi-actions{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:17px}.humi-button,.humi-open{border:1px solid #b9d2c2;border-radius:8px;background:white;color:#235a47;padding:9px 13px;font:650 13px system-ui;cursor:pointer;text-decoration:none;display:inline-block}.humi-button.primary{background:var(--humi-primary);border-color:var(--humi-primary);color:white}.humi-button:disabled{opacity:.45;cursor:not-allowed}.humi-button:not(:disabled):hover{filter:brightness(.95)}.humi-warning,.humi-preview-info.humi-warning{background:#fff6e7;border:1px solid #f1deb9;color:#7c5216;border-radius:9px;padding:8px 11px}.humi-warnings{margin:5px 0 11px;padding-left:22px;font-size:12px;color:#765221}.humi-status{color:#466b5a;font-size:12px;min-height:18px}.humi-error{color:#ab3332!important}.humi-paper{max-height:min(65vh,850px);min-height:160px;overflow:auto;padding:12px;background:white;border:1px solid #d6e4da;border-radius:12px;margin:12px 0}.humi-paper svg{max-width:100%!important;height:auto!important;display:block}.humi-preview-info{color:#526e5d;font-size:12px;margin:5px 0 12px}.humi-source{margin:16px 0 8px;border:1px